"use client"

// AsciiArt — "HANZO Secure Shield Hex", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=97438cfd-a0b5-4bf6-bf9d-43a752e80ac3
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_3GPGUGW0kezwI1M261bFhugwynL/f36e0877-7542-4f6b-9c1d-904fba3c6d7e.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_3GPGUGW0kezwI1M261bFhugwynL/8b803fd0-45be-4499-b628-00f1585633b8.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"HANZO Secure Shield Hex — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

